package com.afirma.assina;
import java.util.*;

/** Representação Definicao/Metadata gerada por TabelaChatbotDefinicao na origem. */
public final class CompiladorBotAutentica {
 private CompiladorBotAutentica(){}
 @SuppressWarnings("unchecked") public static Map<String,Object> compilar(Map<String,Object> fluxo){var tarefas=new ArrayList<Map<String,Object>>();var metadata=new LinkedHashMap<String,Object>();metadata.put("BotIniciado",false);metadata.put("TarefaAtual","");metadata.put("BotFinalizado",false);metadata.put("Variaveis",Map.of());
  for(var objeto:(List<?>)fluxo.getOrDefault("nodes",List.of())){var no=(Map<String,Object>)objeto;String id=no.get("id").toString(),tipo=Objects.toString(no.get("type"),"");if(!Set.of("tarefa","script","integracao").contains(tipo))continue;var d=no.get("data") instanceof Map<?,?> m?(Map<String,Object>)m:Map.<String,Object>of();var t=new LinkedHashMap<String,Object>();t.put("nome",id);var perguntas=new ArrayList<Object>();var respostas=new ArrayList<Object>();var acoes=new ArrayList<Object>();t.put("pergunta",perguntas);t.put("respostas",respostas);t.put("acoes",acoes);
   metadata.put(id+"_Executado",false);metadata.put(id+"_Resposta","");
   if(tipo.equals("tarefa")){if(d.get("pergunta") instanceof String p&&!p.isBlank())perguntas.add(Map.of("tipo","texto","conteudo",p));else t.put("tarefaAutomatica",true);if(d.get("resposta") instanceof String r&&!r.isBlank())respostas.add(Map.of("tipo","texto","conteudo",r));}
   else{t.put("tarefaAutomatica",true);metadata.put(id+"_Executado",false);metadata.put(id+"_Resposta","");var scripts=new ArrayList<Object>();t.put("scripts",scripts);String subtipo=Objects.toString(d.get("tipo"),"");if(subtipo.equals("gerar_atendimento"))scripts.add(Map.of("nome","GerarAtendimento","caminho","/ScriptsChatbot/GerarAtendimento","parametros",Map.of("ContatoId","","CanalId","","ClienteId","","SetorId","")));if(subtipo.equals("transferir_setor")&&d.get("setor") instanceof Map<?,?> setor)t.put("constante",Map.of("nome","SetorId","valor",setor.get("id")));
    if(subtipo.equals("rest")){var rest=d.get("restData") instanceof Map<?,?> m?m:Map.of();var script=new LinkedHashMap<String,Object>();script.put("nome","ExecutarAPI");script.put("caminho","/ScriptsChatbot/ExecutarAPI");script.put("API_Externa",true);script.put("Url_API",rest.get("url"));script.put("Metodo_API",rest.get("metodo"));var headers=new LinkedHashMap<String,Object>();if(Boolean.TRUE.equals(rest.get("enviarHeaders"))&&rest.get("headers") instanceof List<?> hs)for(Object h:hs)if(h instanceof Map<?,?> m)headers.put(Objects.toString(m.get("chave")),m.get("valor"));script.put("Headers_API",headers);var qs=new ArrayList<String>();if(Boolean.TRUE.equals(rest.get("enviarQueryParameters"))&&rest.get("queryParameters") instanceof List<?> ps)for(Object p:ps)if(p instanceof Map<?,?> m)qs.add(java.net.URLEncoder.encode(Objects.toString(m.get("nome")),java.nio.charset.StandardCharsets.UTF_8)+"="+java.net.URLEncoder.encode(Objects.toString(m.get("valor")),java.nio.charset.StandardCharsets.UTF_8));script.put("QueryParams_API",String.join("&",qs));script.put("Body_API",Objects.toString(rest.get("body"),""));scripts.add(script);}
    if(subtipo.equals("hControl")){scripts.add(Map.of("nome","hControl","caminho","/ScriptsChatbot/BuscarBoletos_hControl","CPFCNPJ","","clientId","","secretId",""));var h=d.get("hControlData") instanceof Map<?,?> m?m:Map.of();t.put("constante",List.of(Map.of("nome","clientId","valor",Objects.toString(h.get("clientId"),"")),Map.of("nome","secretId","valor",Objects.toString(h.get("secretId"),""))));}
    if(d.get("destino_transferir") instanceof String destino&&!destino.isBlank()&&!destino.equals("end"))acoes.add(Map.of("nome","transferir_tarefa","valor",destino,"condicao",""));
   }
   if(!tipo.equals("script")){if(d.get("acoes") instanceof List<?> as)for(Object a:as)if(a instanceof Map<?,?> m&&!"end".equals(m.get("valor")))acoes.add(m);if(d.get("variavel") instanceof String v&&!v.isBlank())t.put("variavel","&"+v.toUpperCase(Locale.ROOT));}
   tarefas.add(t);
  }
  for(Object objeto:(List<?>)fluxo.getOrDefault("edges",List.of())){var edge=(Map<?,?>)objeto;for(var t:tarefas){if("start".equals(edge.get("source"))&&Objects.equals(t.get("nome"),edge.get("target")))t.put("tarefaInicial",true);if("end".equals(edge.get("target"))&&Objects.equals(t.get("nome"),edge.get("source")))((List<Object>)t.get("acoes")).add(Map.of("nome","finalizar_chatbot","valor","","condicao",""));}}
  return Map.of("Definicao",Map.of("tarefa",tarefas,"falha",Map.of("respostas",List.of(Map.of("tipo","texto","conteudo","Ops, não entendi o que você falou, verifique a pergunta e tente *responder novamente*.")))),"Metadata",metadata);
 }
}
